using Challenge;void P(string id,bool ok)=>Console.WriteLine($"{id}|{(ok?"pass":"fail")}");P("C01",true);var f=new F();var r=await new Aggregator(f,2).FetchAllAsync(["a","b","c"]);P("C02",r.SequenceEqual(["a","b","c"]));P("C03",f.Peak<=2);var cts=new CancellationTokenSource();cts.Cancel();try{await new Aggregator(new F(),1).FetchAllAsync(["x"],cts.Token);P("C04",false);}catch(OperationCanceledException){P("C04",true);}P("C05",(await new Aggregator(new F()).FetchAllAsync([])).Count==0);class F:IRemote{int active;public int Peak;public async Task<string> FetchAsync(string id,CancellationToken ct){var n=Interlocked.Increment(ref active);Peak=Math.Max(Peak,n);try{await Task.Delay(20,ct);return id;}finally{Interlocked.Decrement(ref active);}}}
